/**
 * ADMIN 이 주문서 동의 뒤 카드 등록을 연다. 금액·provider 는 받지 않고 서버가 상품 버전으로 정해 굳힌다. 새로 연 등록은 201 과 registration(state 원문이 실려 한 번만 나간다), 같은 requestKey 재전송·본인 진행 중 등록은 200 과 registration=null 이다. 다른 ADMIN 의 진행 중 등록이 있으면 409 BILLING_IN_PROGRESS.
 * @summary 카드 등록 열기
 */
export const createBillingSetup = async (
  workspaceId: string,
  createBillingSetupRequest?: CreateBillingSetupRequest,
  options?: Parameters<typeof apiFetch>[1]
): Promise<createBillingSetupResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string]
        )
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<createBillingSetupResponse>(
    getCreateBillingSetupUrl(workspaceId),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(createBillingSetupRequest),
    }
  );
};

